'use client';

import Link from 'next/link';
import { useState } from 'react';
import type { Ticket } from '../../lib/handoff';

/**
 * The ticket desk: one button issues a ticket whose code, colour and desk are
 * generated by the app. They are shown here and nowhere else — the gate page
 * never displays them — so a later step can only know them from what an
 * earlier step saw.
 */
export function DeskClient() {
  const [ticket, setTicket] = useState<Ticket | undefined>();

  async function issue() {
    const response = await fetch('/api/handoff', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ type: 'issue' }),
    });
    setTicket((await response.json()) as Ticket);
  }

  return (
    <main>
      <h1>Ticket desk</h1>
      <p>Press the button to receive your visitor ticket. Keep the details: the gate will ask for them.</p>
      {ticket === undefined ? (
        <button type="button" onClick={issue}>
          Issue ticket
        </button>
      ) : (
        <section aria-label="Your ticket" className="panel">
          <p role="status" aria-label="Ticket">
            Ticket {ticket.code} · colour {ticket.colour} · desk {ticket.desk}
          </p>
        </section>
      )}
      <nav aria-label="Visitor">
        <Link href="/handoff/gate">Gate</Link> · <Link href="/procure/suppliers">Procurement</Link>
      </nav>
    </main>
  );
}
